function printUsage() {
  console.log(`Usage: node ${PATCH_ID}.mjs [--dry-run] [--root=<folder>]`);
}

function sha256(buffer) {
  return createHash("sha256").update(buffer).digest("hex");
}

function resolveTarget(root, relativePath) {
  if (path.isAbsolute(relativePath)) {
    throw new Error(`Unsafe absolute path in patcher manifest: ${relativePath}`);
  }
  const parts = relativePath.split("/");
  if (parts.includes("..") || parts.includes("")) {
    throw new Error(`Unsafe path in patcher manifest: ${relativePath}`);
  }
  const target = path.resolve(root, ...parts);
  const rootWithSep = root.endsWith(path.sep) ? root : root + path.sep;
  if (target !== root && !target.startsWith(rootWithSep)) {
    throw new Error(`Path escapes the target folder: ${relativePath}`);
  }
  return target;
}

function main() {
  const args = process.argv.slice(2);
  let dryRun = false;
  let rootArg = null;
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === "--dry-run") dryRun = true;
    else if (arg === "--help" || arg === "-h") { printUsage(); return; }
    else if (arg.startsWith("--root=")) rootArg = arg.slice("--root=".length);
    else if (arg === "--root" && i + 1 < args.length) { rootArg = args[i + 1]; i += 1; }
    else throw new Error(`Unknown argument: ${arg}`);
  }

  const scriptDir = path.dirname(fileURLToPath(import.meta.url));
  const root = path.resolve(rootArg ?? scriptDir);
  if (!dryRun) fs.mkdirSync(root, { recursive: true });

  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const backupDir = path.join(root, ".patcher-backups", PATCH_ID, stamp);

  let created = 0;
  let updated = 0;
  let skipped = 0;
  let backedUp = false;

  for (const file of FILES) {
    if (file.path === ".env") {
      console.log("[SKIP]   .env (patchers never touch your .env file)");
      skipped += 1;
      continue;
    }
    const content = Buffer.from(file.b64, "base64");
    if (sha256(content) !== file.sha256) {
      throw new Error(`Patcher data is corrupted for ${file.path}. Download the patcher again.`);
    }
    const target = resolveTarget(root, file.path);

    if (fs.existsSync(target)) {
      const existing = fs.readFileSync(target);
      if (existing.equals(content)) {
        console.log(`[SKIP]   ${file.path}`);
        skipped += 1;
        continue;
      }
      if (dryRun) {
        console.log(`[UPDATE] ${file.path} (dry-run)`);
        updated += 1;
        continue;
      }
      const backupTarget = path.join(backupDir, ...file.path.split("/"));
      fs.mkdirSync(path.dirname(backupTarget), { recursive: true });
      fs.copyFileSync(target, backupTarget);
      backedUp = true;
      fs.writeFileSync(target, content);
      if (sha256(fs.readFileSync(target)) !== file.sha256) {
        throw new Error(`Write verification failed for ${file.path}.`);
      }
      console.log(`[UPDATE] ${file.path}`);
      updated += 1;
    } else {
      if (dryRun) {
        console.log(`[CREATE] ${file.path} (dry-run)`);
        created += 1;
        continue;
      }
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, content);
      if (sha256(fs.readFileSync(target)) !== file.sha256) {
        throw new Error(`Write verification failed for ${file.path}.`);
      }
      console.log(`[CREATE] ${file.path}`);
      created += 1;
    }
  }

  console.log("");
  console.log(
    `${PATCH_ID}: created=${created} updated=${updated} skipped=${skipped}` +
      (dryRun ? " (dry-run: nothing was changed)" : "")
  );
  if (backedUp) console.log(`Backups of changed files: ${backupDir}`);
  if (!dryRun) {
    console.log("");
    console.log("Next steps (PowerShell, inside this folder):");
    console.log("  python -m venv .venv");
    console.log("  .\\.venv\\Scripts\\Activate.ps1");
    console.log("  python -m pip install --upgrade pip");
    console.log('  python -m pip install -e ".[dev]"');
    console.log("  python -m pytest -q");
    console.log("  python -m ruff check");
    console.log("  pc-agent --version");
    console.log("  pc-agent doctor");
    console.log("  pc-agent files search report --content");
    console.log("  pc-agent gui --check");
    console.log("");
    console.log("If Activate.ps1 is blocked, use .\\.venv\\Scripts\\python.exe and .\\.venv\\Scripts\\pc-agent.exe directly.");
  }
}

try {
  main();
} catch (error) {
  console.error(`ERROR: ${error.message}`);
  process.exitCode = 1;
}
